/**
 * Batch 3 — ~110 verified India Quiz questions.
 * Prioritises categories with the largest gaps:
 *   cat-edu (25→35), cat-civics (26→36), cat-sports (26→36), cat-culture (26→36),
 *   cat-science (27→37), cat-history (28→38), cat-geography (28→38),
 *   cat-gk (31→41), cat-economy (30→40), cat-environment (30→40), cat-art (30→40).
 * ~10 per category × 11 categories = 110 questions.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string;
  categoryId: string;
  text: string;
  options: [string, string, string, string];
  correctIndex: number;
  explanation: string;
  source: string;
  difficulty: 'easy' | 'medium' | 'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk: General Knowledge (10) ═══
  { slug: 'gk-national-mineral', categoryId: 'cat-gk', text: 'Which mineral is known as the "black gold" of India due to its economic importance?', options: ['Iron ore', 'Coal', 'Bauxite', 'Manganese'], correctIndex: 1, explanation: 'Coal is often called the "black gold" of India because of its critical role in power generation, steel production, and industrial development. India has the 4th largest coal reserves in the world.', source: 'Ministry of Coal, Government of India', difficulty: 'medium' },
  { slug: 'gk-indian-standard-time', categoryId: 'cat-gk', text: 'Indian Standard Time (IST) is based on the longitude of which city?', options: ['Delhi', 'Mumbai', 'Allahabad (Prayagraj)', 'Kolkata'], correctIndex: 2, explanation: 'IST is based on the longitude 82.5°E passing through Allahabad (now Prayagraj), Uttar Pradesh. IST is UTC+5:30, calculated from the Mirzapur observatory near Allahabad.', source: 'India Meteorological Department / Survey of India', difficulty: 'hard' },
  { slug: 'gk-padma-awards-types', categoryId: 'cat-gk', text: 'The Padma Awards are given in how many categories?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 1, explanation: 'The Padma Awards are given in three categories: Padma Vibhushan (second highest civilian award), Padma Bhushan (third highest), and Padma Shri (fourth highest). They are announced on Republic Day.', source: 'Ministry of Home Affairs, Government of India', difficulty: 'easy' },
  { slug: 'gk-bharat-ratna-first', categoryId: 'cat-gk', text: 'Who was the first recipient of the Bharat Ratna, India\'s highest civilian award?', options: ['Dr. S. Radhakrishnan', 'C. Rajagopalachari', 'Dr. Rajendra Prasad', 'Jawaharlal Nehru'], correctIndex: 1, explanation: 'C. Rajagopalachari (the last Governor-General of India) was among the first three recipients of the Bharat Ratna in 1954, along with Dr. S. Radhakrishnan and C.V. Raman.', source: 'Ministry of Home Affairs, Government of India', difficulty: 'medium' },
  { slug: 'gk-arjuna-award-sport', categoryId: 'cat-gk', text: 'The Arjuna Award is given for outstanding performance in which field?', options: ['Literature', 'Sports', 'Science', 'Social service'], correctIndex: 1, explanation: 'The Arjuna Award is India\'s second-highest sporting honour (after the Khel Ratna), given for outstanding performance in sports and games. It was instituted in 1961.', source: 'Ministry of Youth Affairs and Sports', difficulty: 'easy' },
  { slug: 'gk-national-voting-age-amendment', categoryId: 'cat-gk', text: 'The voting age in India was reduced from 21 to 18 years by which Constitutional Amendment?', options: ['42nd Amendment (1976)', '52nd Amendment (1985)', '61st Amendment (1988)', '73rd Amendment (1992)'], correctIndex: 2, explanation: 'The 61st Constitutional Amendment Act of 1988 reduced the voting age from 21 to 18 years for Lok Sabha and Assembly elections, effective from the 1989 general election.', source: 'Constitution of India, 61st Amendment Act', difficulty: 'medium' },
  { slug: 'gk-largest-railway-network', categoryId: 'cat-gk', text: 'Indian Railways is among the largest railway networks in the world. What is its approximate route length?', options: ['About 48,000 km', 'About 68,000 km', 'About 88,000 km', 'About 108,000 km'], correctIndex: 1, explanation: 'Indian Railways has approximately 68,000 route kilometres, making it the 4th largest railway network in the world (after USA, China, and Russia). It is the largest employer in India with over 1.3 million employees.', source: 'Indian Railways / Ministry of Railways', difficulty: 'medium' },
  { slug: 'gk-golden-quadrilateral', categoryId: 'cat-gk', text: 'The Golden Quadrilateral highway project connects which four Indian cities?', options: ['Delhi, Mumbai, Chennai, Kolkata', 'Delhi, Mumbai, Bengaluru, Kolkata', 'Delhi, Jaipur, Mumbai, Chennai', 'Mumbai, Delhi, Chennai, Hyderabad'], correctIndex: 0, explanation: 'The Golden Quadrilateral connects Delhi, Mumbai, Chennai, and Kolkata — the four major metropolitan cities of India. It is approximately 5,846 km long and was completed by the National Highways Authority of India (NHAI).', source: 'National Highways Authority of India (NHAI)', difficulty: 'medium' },
  { slug: 'gk-island-groups-india', categoryId: 'cat-gk', text: 'India has two major groups of islands in the Arabian Sea and Bay of Bengal. Which pair is correct?', options: ['Andaman & Nicobar (Arabian Sea) and Lakshadweep (Bay of Bengal)', 'Andaman & Nicobar (Bay of Bengal) and Lakshadweep (Arabian Sea)', 'Both in Arabian Sea', 'Both in Bay of Bengal'], correctIndex: 1, explanation: 'The Andaman & Nicobar Islands are in the Bay of Bengal (south-east of India), while Lakshadweep is in the Arabian Sea (south-west of India). The Andaman & Nicobar Islands are closer to Myanmar and Indonesia than to mainland India.', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'gk-longest-tunnel-india', categoryId: 'cat-gk', text: 'Which is the longest road tunnel in India?', options: ['Jawahar Tunnel (J&K)', 'Atal Tunnel (Himachal Pradesh)', 'Banihal Qazigund Road Tunnel', 'Chenani-Nashri Tunnel'], correctIndex: 1, explanation: 'The Atal Tunnel (formerly Rohtang Tunnel) in Himachal Pradesh is the longest road tunnel in India at 9.02 km. It was inaugurated on 3 October 2020 and connects Manali to Lahaul-Spiti valley year-round.', source: 'Border Roads Organisation (BRO) / Ministry of Defence', difficulty: 'medium' },

  // ═══ cat-history: Indian History (10) ═══
  { slug: 'hist-indus-valley-script', categoryId: 'cat-history', text: 'The script of the Indus Valley Civilisation remains undeciphered. Approximately how many distinct signs have been identified?', options: ['About 100', 'About 400', 'About 1,000', 'About 5,000'], correctIndex: 1, explanation: 'Approximately 400 distinct signs have been identified in the Indus Valley script. Despite numerous attempts by scholars worldwide, the script remains undeciphered, making it one of the great mysteries of ancient history.', source: 'Archaeological Survey of India', difficulty: 'hard' },
  { slug: 'hist-buddhist-councils', categoryId: 'cat-history', text: 'How many Buddhist Councils were held in ancient India after the death of Gautama Buddha?', options: ['Two', 'Three', 'Four', 'Six'], correctIndex: 2, explanation: 'Four Buddhist Councils were held: the first at Rajgriha (c. 483 BCE), the second at Vaishali (c. 383 BCE), the third at Pataliputra (c. 250 BCE under Ashoka), and the fourth in Kashmir (c. 72 CE under Kanishka).', source: 'Indian Council of Historical Research', difficulty: 'hard' },
  { slug: 'hist-delhi-sultanate-founder', categoryId: 'cat-history', text: 'Who founded the Delhi Sultanate in 1206 CE?', options: ['Qutb-ud-din Aibak', 'Iltutmish', 'Razia Sultan', 'Alauddin Khalji'], correctIndex: 0, explanation: 'Qutb-ud-din Aibak, a former slave of Muhammad Ghori, founded the Delhi Sultanate (Mamluk/Slave Dynasty) in 1206 CE. He started construction of the Qutub Minar, which was completed by Iltutmish.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-razia-sultan', categoryId: 'cat-history', text: 'Razia Sultan was the first woman to rule the Delhi Sultanate. In which century did she rule?', options: ['11th century', '12th century', '13th century', '14th century'], correctIndex: 2, explanation: 'Razia Sultan (Raziya al-Din) ruled the Delhi Sultanate from 1236 to 1240 CE (13th century). She was the daughter of Iltutmish and the only woman to sit on the throne of the Delhi Sultanate.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-mughal-last-emperor', categoryId: 'cat-history', text: 'Who was the last Mughal Emperor of India?', options: ['Shah Alam II', 'Akbar Shah II', 'Bahadur Shah Zafar', 'Alamgir II'], correctIndex: 2, explanation: 'Bahadur Shah Zafar II (1775-1862) was the last Mughal Emperor. He was exiled to Rangoon (Yangon) by the British after the 1857 uprising. He was also a noted Urdu poet.', source: 'National Archives of India', difficulty: 'easy' },
  { slug: 'hist-mathura-school-art', categoryId: 'cat-history', text: 'The Mathura school of art, known for its distinctive style of sculpture, flourished under which dynasty?', options: ['Mauryas', 'Kushanas', 'Guptas', 'Cholas'], correctIndex: 1, explanation: 'The Mathura school of art flourished under the Kushana dynasty (1st-3rd century CE). It is known for its red sandstone sculptures and was the first to produce Buddha images in human form, distinct from the earlier Gandhara school.', source: 'Archaeological Survey of India / National Museum', difficulty: 'medium' },
  { slug: 'hist-lothal-dockyard', categoryId: 'cat-history', text: 'The Indus Valley site of Lothal in Gujarat is famous for having what archaeological feature?', options: ['A royal palace', 'A dockyard (world\'s earliest known)', 'A Buddhist stupa', 'A stepwell'], correctIndex: 1, explanation: 'Lothal is famous for its dockyard — considered the world\'s earliest known tidal dockyard. Dating to c. 2400 BCE, it demonstrates the maritime trade capabilities of the Indus Valley Civilisation.', source: 'Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'hist-1857-centre-delhi', categoryId: 'cat-history', text: 'During the 1857 uprising, Bahadur Shah Zafar was proclaimed the symbolic leader of the rebellion in which city?', options: ['Lucknow', 'Kanpur', 'Delhi', 'Jhansi'], correctIndex: 2, explanation: 'Bahadur Shah Zafar was proclaimed the symbolic leader of the 1857 uprising in Delhi. The sepoys who mutinied in Meerat marched to Delhi to seek his blessings. The British recaptured Delhi on 20 September 1857.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-travancore-temple-entry', categoryId: 'cat-history', text: 'The historic Temple Entry Proclamation allowing lower castes to enter Hindu temples was issued in which princely state in 1936?', options: ['Mysore', 'Travancore', 'Baroda', 'Hyderabad'], correctIndex: 1, explanation: 'The Temple Entry Proclamation was issued by Maharaja Chithira Thirunal Balarama Varma of Travancore on 12 November 1936. It allowed all Hindus, regardless of caste, to enter temples — a landmark in social reform.', source: 'Indian Council of Historical Research / Kerala State Archives', difficulty: 'hard' },
  { slug: 'hist-subhas-chandra-ina', categoryId: 'cat-history', text: 'Subhas Chandra Bose reorganised the Indian National Army (INA) in which year?', options: ['1940', '1942', '1943', '1945'], correctIndex: 2, explanation: 'Subhas Chandra Bose reorganised the INA in 1943 in Singapore, after taking over leadership from Rash Behari Bose. The INA fought alongside the Japanese against British forces in the Burma-India theatre during World War II.', source: 'National Archives of India', difficulty: 'medium' },

  // ═══ cat-geography: Geography (10) ═══
  { slug: 'geo-zanskar-range', categoryId: 'cat-geography', text: 'The Zanskar Range is a mountain range in which region of India?', options: ['Himachal Pradesh', 'Ladakh', 'Uttarakhand', 'Sikkim'], correctIndex: 1, explanation: 'The Zanskar Range is located in the Union Territory of Ladakh. It separates Zanskar (to the south) from Ladakh (to the north). It is part of the Trans-Himalayan system and has peaks exceeding 6,000 m.', source: 'Geological Survey of India', difficulty: 'medium' },
  { slug: 'geo-mahanadi-river-state', categoryId: 'cat-geography', text: 'The Mahanadi river flows primarily through which Indian state?', options: ['Odisha', 'Chhattisgarh', 'Jharkhand', 'West Bengal'], correctIndex: 0, explanation: 'The Mahanadi (857 km) flows primarily through Odisha and Chhattisgarh. It originates in the Dandakaranya plateau in Chhattisgarh and drains into the Bay of Bengal near Cuttack, Odisha.', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'easy' },
  { slug: 'geo-kanchenjunga-rank', categoryId: 'cat-geography', text: 'Kanchenjunga, the highest mountain peak in India, is the what highest peak in the world?', options: ['Second highest', 'Third highest', 'Fifth highest', 'Tenth highest'], correctIndex: 1, explanation: 'Kanchenjunga (8,586 m) is the third highest mountain peak in the world, after Mount Everest (8,849 m) and K2 (8,611 m). It is located on the border between Sikkim (India) and Nepal.', source: 'Survey of India / Geological Survey of India', difficulty: 'medium' },
  { slug: 'geo-srinagar-altitude', categoryId: 'cat-geography', text: 'Srinagar, the summer capital of Jammu & Kashmir, is situated on the banks of which river?', options: ['Chenab', 'Jhelum', 'Ravi', 'Tawi'], correctIndex: 1, explanation: 'Srinagar is situated on the banks of the Jhelum river. The city is also known for its Dal Lake and Mughal gardens. Srinagar is at an altitude of approximately 1,585 m above sea level.', source: 'Jammu & Kashmir Tourism / Survey of India', difficulty: 'easy' },
  { slug: 'geo-diamond-cross-state', categoryId: 'cat-geography', text: 'The Tropic of Cancer does NOT pass through which of these Indian states?', options: ['Rajasthan', 'Madhya Pradesh', 'Odisha', 'Jharkhand'], correctIndex: 2, explanation: 'The Tropic of Cancer passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram. It does NOT pass through Odisha.', source: 'Survey of India', difficulty: 'medium' },
  { slug: 'geo-port-blair-location', categoryId: 'cat-geography', text: 'Port Blair, the capital of Andaman & Nicobar Islands, is located in which body of water?', options: ['Arabian Sea', 'Bay of Bengal', 'Indian Ocean', 'Andaman Sea'], correctIndex: 1, explanation: 'Port Blair is located in the Bay of Bengal. The Andaman & Nicobar Islands are a chain of 572 islands stretching southward from Myanmar to Sumatra, separating the Bay of Bengal from the Andaman Sea.', source: 'Andaman & Nicobar Administration', difficulty: 'medium' },
  { slug: 'geo-ladakh-highest-pass', categoryId: 'cat-geography', text: 'Khardung La, one of the highest motorable roads in the world, is located in which region?', options: ['Himachal Pradesh', 'Ladakh', 'Sikkim', 'Uttarakhand'], correctIndex: 1, explanation: 'Khardung La pass is located in Ladakh, at an altitude of approximately 5,359 m (17,582 ft). It connects Leh to the Nubra Valley and Shyok River valley. It is maintained by the Border Roads Organisation (BRO).', source: 'Border Roads Organisation / Ministry of Defence', difficulty: 'medium' },
  { slug: 'geo-godavari-tributary', categoryId: 'cat-geography', text: 'Which river is the principal tributary of the Godavari?', options: ['Manjira', 'Pranahita', 'Indravati', 'Wardha'], correctIndex: 1, explanation: 'The Pranahita is the largest tributary of the Godavari river. It is formed by the confluence of the Wardha and Wainganga rivers. The Godavari is the second-longest river in India (after the Ganga system) at about 1,465 km.', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'hard' },
  { slug: 'geo-wular-lake-size', categoryId: 'cat-geography', text: 'Wular Lake, one of the largest freshwater lakes in Asia, is located in which Indian state/UT?', options: ['Himachal Pradesh', 'Jammu & Kashmir', 'Uttarakhand', 'Ladakh'], correctIndex: 1, explanation: 'Wular Lake is located in Jammu & Kashmir. It is one of the largest freshwater lakes in Asia, covering approximately 200 sq km. It was formed by tectonic activity and is fed by the Jhelum river.', source: 'Jammu & Kashmir Tourism / Ministry of Environment', difficulty: 'medium' },
  { slug: 'geo-monsoon-onset-kerala', categoryId: 'cat-geography', text: 'The southwest monsoon in India typically arrives first in which state around 1 June?', options: ['Tamil Nadu', 'Kerala', 'Karnataka', 'Goa'], correctIndex: 1, explanation: 'The southwest monsoon arrives in Kerala around 1 June each year, then progresses northward. Tamil Nadu receives most of its rainfall from the northeast (retreating) monsoon in October-November, not the southwest monsoon.', source: 'India Meteorological Department (IMD)', difficulty: 'medium' },

  // ═══ cat-civics: Constitution & Civics (10) ═══
  { slug: 'civ-const-came-into-effect', categoryId: 'cat-civics', text: 'The Indian Constitution came into full effect on which date?', options: ['15 August 1947', '26 November 1949', '26 January 1950', '1 August 1950'], correctIndex: 2, explanation: 'The Constitution came into full effect on 26 January 1950 — celebrated as Republic Day. It was adopted (signed) by the Constituent Assembly on 26 November 1949 (now Constitution Day), but most provisions came into force on 26 January 1950.', source: 'Constitution of India', difficulty: 'medium' },
  { slug: 'civ-const-parts-count', categoryId: 'cat-civics', text: 'The original Indian Constitution had how many parts (divisions)?', options: ['18', '22', '25', '395'], correctIndex: 1, explanation: 'The original Constitution had 22 Parts, 395 Articles, and 8 Schedules. After amendments, it now has 25 Parts, 448 Articles (approximately), and 12 Schedules.', source: 'Constitution of India', difficulty: 'medium' },
  { slug: 'civ-directive-principles-nature', categoryId: 'cat-civics', text: 'The Directive Principles of State Policy (Part IV) are described in the Constitution as what?', options: ['Enforceable by courts', 'Fundamental to governance but not enforceable', 'Advisory only', 'Temporary provisions'], correctIndex: 1, explanation: 'Article 37 states that Directive Principles are "fundamental in the governance of the country" but are not enforceable by any court. They guide the government in making laws and policies.', source: 'Constitution of India, Part IV, Article 37', difficulty: 'medium' },
  { slug: 'civ-zero-hour-parliament', categoryId: 'cat-civics', text: 'In Indian parliamentary procedure, what is "Zero Hour"?', options: ['The time between sessions', 'The period immediately before the Question Hour', 'The time for matters raised without prior notice', 'The lunch break'], correctIndex: 2, explanation: 'Zero Hour is the period in Indian Parliament (starting at 12 noon) when members can raise matters of urgent public importance without prior notice. It is an Indian innovation not found in the rules of procedure but has become a regular feature since 1962.', source: 'Parliament of India / Lok Sabha Secretariat', difficulty: 'hard' },
  { slug: 'civ-no-confidence-motion', categoryId: 'cat-civics', text: 'A no-confidence motion against the government can be moved only in which house?', options: ['Rajya Sabha', 'Lok Sabha', 'Both houses jointly', 'Neither house'], correctIndex: 1, explanation: 'A no-confidence motion can be moved only in the Lok Sabha (Article 75). The Rajya Sabha cannot remove the Council of Ministers — it can only discuss, not vote on, their confidence.', source: 'Constitution of India, Article 75', difficulty: 'medium' },
  { slug: 'civ-governor-discretion', categoryId: 'cat-civics', text: 'Under which Article of the Constitution does the Governor have discretionary powers?', options: ['Article 154', 'Article 163', 'Article 174', 'Article 356'], correctIndex: 1, explanation: 'Article 163 provides for a Council of Ministers to aid and advise the Governor, but allows the Governor to exercise discretion in certain matters. This is unique to state governors — the President has no explicit discretionary powers.', source: 'Constitution of India, Article 163', difficulty: 'hard' },
  { slug: 'civ-cooperative-societies', categoryId: 'cat-civics', text: 'Cooperative societies in India come under which list of the Constitution?', options: ['Union List', 'State List', 'Concurrent List', 'Residuary powers'], correctIndex: 1, explanation: 'Cooperative societies fall under the State List (Entry 32) of the Seventh Schedule. The 97th Constitutional Amendment (2011) added Part IXB (Articles 243ZH-243ZT) for uniform cooperative laws, but the subject remains primarily with states.', source: 'Constitution of India, Seventh Schedule / 97th Amendment', difficulty: 'hard' },
  { slug: 'civ-municipalities-article', categoryId: 'cat-civics', text: 'Municipalities in India were given constitutional status by which Amendment and under which Article?', options: ['73rd Amendment, Article 243G', '74th Amendment, Article 243W', '42nd Amendment, Article 40', '86th Amendment, Article 21A'], correctIndex: 1, explanation: 'The 74th Constitutional Amendment (1992) gave constitutional status to urban local bodies (municipalities) through Part IXA and Article 243W. This was the urban counterpart to the 73rd Amendment for rural panchayats.', source: 'Constitution of India, 74th Amendment Act / Part IXA', difficulty: 'medium' },
  { slug: 'civ-writ-jurisdiction-hc', categoryId: 'cat-civics', text: 'Under which Article can a High Court issue writs for the enforcement of fundamental rights?', options: ['Article 32', 'Article 226', 'Article 227', 'Article 136'], correctIndex: 1, explanation: 'Article 226 empowers High Courts to issue writs (habeas corpus, mandamus, prohibition, certiorari, and quo warranto) not only for fundamental rights but also for any other legal right. The Supreme Court can issue writs only under Article 32.', source: 'Constitution of India, Articles 32 and 226', difficulty: 'medium' },
  { slug: 'civ-minimum-age-mp', categoryId: 'cat-civics', text: 'What is the minimum age to become a member of the Lok Sabha?', options: ['18 years', '21 years', '25 years', '30 years'], correctIndex: 2, explanation: 'The minimum age to become a member of the Lok Sabha is 25 years (Article 84). For the Rajya Sabha, it is 30 years. The minimum age to vote in elections is 18 years.', source: 'Constitution of India, Article 84', difficulty: 'easy' },

  // ═══ cat-science: Science & Technology (10) ═══
  { slug: 'sci-aiims-establishment-year', categoryId: 'cat-science', text: 'AIIMS New Delhi was established in which year?', options: ['1947', '1952', '1956', '1960'], correctIndex: 2, explanation: 'AIIMS New Delhi was established as an institution of national importance by an Act of Parliament in 1956 (AIIMS Act, 1956). It began operations in 1956 and was inaugurated in 1960.', source: 'AIIMS New Delhi / Ministry of Health', difficulty: 'medium' },
  { slug: 'sci-isro-headquarters', categoryId: 'cat-science', text: 'ISRO is headquartered in which city?', options: ['New Delhi', 'Bengaluru', 'Hyderabad', 'Mumbai'], correctIndex: 1, explanation: 'ISRO is headquartered in Bengaluru, Karnataka. Its main launch facilities are at Satish Dhawan Space Centre (Sriharikota, Andhra Pradesh) and its main satellite centre is at Bengaluru.', source: 'ISRO official website', difficulty: 'easy' },
  { slug: 'sci-indian-pharma-largest', categoryId: 'cat-science', text: 'India is the largest provider of generic drugs globally. What percentage of global generic drug supply does India provide (approximately)?', options: ['About 10%', 'About 20%', 'About 35%', 'About 50%'], correctIndex: 1, explanation: 'India supplies approximately 20% of global generic drugs by volume. The Indian pharmaceutical industry is the 3rd largest by volume and 14th by value. India is also the largest vaccine producer in the world.', source: 'Department of Pharmaceuticals, Ministry of Chemicals and Fertilisers', difficulty: 'medium' },
  { slug: 'sci-drdhq-headquarters', categoryId: 'cat-science', text: 'The Defence Research and Development Organisation (DRDO) is headquartered in which city?', options: ['Bengaluru', 'Hyderabad', 'New Delhi', 'Pune'], correctIndex: 2, explanation: 'DRDO is headquartered in New Delhi. It operates over 50 laboratories across India and develops defence technologies including missiles, aircraft, radar systems, and electronic warfare systems.', source: 'DRDO / Ministry of Defence', difficulty: 'medium' },
  { slug: 'sci-dna-fingerprint-india', categoryId: 'cat-science', text: 'Who is known as the "father of DNA fingerprinting" in India?', options: ['Dr. K. VijayRaghavan', 'Dr. Lalji Singh', 'Dr. G. Padmanaban', 'Dr. P. Rama Rao'], correctIndex: 1, explanation: 'Dr. Lalji Singh (1947-2017) is known as the "father of DNA fingerprinting" in India. He developed the DNA fingerprinting technology at the Centre for Cellular and Molecular Biology (CCMB), Hyderabad, and founded the Laboratory for the Conservation of Endangered Species (LaCONES).', source: 'Centre for Cellular and Molecular Biology (CCMB)', difficulty: 'hard' },
  { slug: 'sci-isro-mars-achievement', categoryId: 'cat-science', text: 'With Mangalyaan, India became the first country to achieve what specific feat?', options: ['Land on Mars', 'Reach Mars orbit on the first attempt', 'Photograph Mars from close range', 'Detect water on Mars'], correctIndex: 1, explanation: 'India (ISRO) became the first country to successfully enter Mars orbit on its first attempt (September 2014). It was also the first Asian country to reach Mars and the mission cost was among the lowest for a Mars mission (approximately $74 million).', source: 'ISRO official website', difficulty: 'easy' },
  { slug: 'sci-it-india-revenue', categoryId: 'cat-science', text: 'India\'s IT industry contributes approximately what percentage to India\'s GDP (as of 2023-24)?', options: ['About 3%', 'About 8%', 'About 15%', 'About 25%'], correctIndex: 1, explanation: 'India\'s IT-BPM (Information Technology - Business Process Management) industry contributes approximately 8% to India\'s GDP. India is the world\'s largest sourcing destination for the IT industry, accounting for about 55% of the global outsourcing market.', source: 'NASSCOM / Ministry of Electronics and IT', difficulty: 'medium' },
  { slug: 'sci-covid-genome-sequencing', categoryId: 'cat-science', text: 'The Indian SARS-CoV-2 Genomics Consortium (INSACOG) was established for what purpose?', options: ['Vaccine development', 'Genome sequencing of COVID-19 variants', 'Clinical trials', 'Drug discovery'], correctIndex: 1, explanation: 'INSACOG was established in December 2020 by the Government of India for genomic surveillance of SARS-CoV-2. It consists of 38 laboratories and monitors variants of the coronavirus by sequencing positive samples from across India.', source: 'Indian Council of Medical Research (ICMR) / Department of Biotechnology', difficulty: 'hard' },
  { slug: 'sci-indian-vaccine-serum', categoryId: 'cat-science', text: 'The Serum Institute of India, the world\'s largest vaccine manufacturer by doses, is located in which city?', options: ['Hyderabad', 'Pune', 'Bengaluru', 'Chennai'], correctIndex: 1, explanation: 'The Serum Institute of India (SII) is headquartered in Pune, Maharashtra. Founded in 1966 by Cyrus Poonawalla, it manufactures over 1.5 billion vaccine doses annually. SII produced Covishield (the AstraZeneca-Oxford COVID-19 vaccine).', source: 'Serum Institute of India / Ministry of Health', difficulty: 'medium' },
  { slug: 'sci-national-mathematics-day', categoryId: 'cat-science', text: 'National Mathematics Day in India is observed on 22 December to mark whose birth anniversary?', options: ['Aryabhata', 'Srinivasa Ramanujan', 'Brahmagupta', 'Bhaskara II'], correctIndex: 1, explanation: 'National Mathematics Day is observed on 22 December to mark the birth anniversary of Srinivasa Ramanujan (1887-1920). He was one of India\'s greatest mathematicians, known for his contributions to number theory, infinite series, and continued fractions.', source: 'Department of Science and Technology, Government of India', difficulty: 'medium' },

  // ═══ cat-sports: Sports (10) ═══
  { slug: 'spt-cricket-oldest-rivalry', categoryId: 'cat-sports', text: 'In Test cricket, India\'s oldest rivalry is against which team?', options: ['Australia', 'Pakistan', 'England', 'West Indies'], correctIndex: 2, explanation: 'India\'s oldest Test cricket rivalry is against England. The first India-England Test was played at Lord\'s in 1932 (India\'s first-ever Test match). The Border-Gavaskar Trophy (India-Australia) is also a major rivalry but began later.', source: 'ESPN Cricinfo / BCCI', difficulty: 'medium' },
  { slug: 'spt-kabaddi-world-cup-india', categoryId: 'cat-sports', text: 'India has won the Kabaddi World Cup (standard format) how many times (as of 2023)?', options: ['Once', 'Twice', 'Three times', 'All editions held'], correctIndex: 3, explanation: 'India has won every edition of the Men\'s Kabaddi World Cup held so far (2004, 2007, 2010, 2011, 2016). Kabaddi is an indigenous Indian contact team sport that originated in ancient India.', source: 'International Kabaddi Federation (IKF) / Amateur Kabaddi Federation of India', difficulty: 'medium' },
  { slug: 'spt-mary-kom-olympic-medal', categoryId: 'cat-sports', text: 'Mary Kom won her Olympic bronze medal in boxing at which Olympics?', options: ['Beijing 2008', 'London 2012', 'Rio 2016', 'Tokyo 2020'], correctIndex: 1, explanation: 'Mary Kom won a bronze medal in the 51 kg flyweight category at the 2012 London Olympics — the first time women\'s boxing was included. She is a 6-time World Amateur Boxing Champion and a Rajya Sabha MP.', source: 'International Olympic Committee / Boxing Federation of India', difficulty: 'medium' },
  { slug: 'spt-cricket-50-runs-fastest', categoryId: 'cat-sports', text: 'The highest individual score in One Day International (ODI) cricket is held by Rohit Sharma. How many runs did he score?', options: ['200', '219', '264', '237'], correctIndex: 2, explanation: 'Rohit Sharma scored 264 runs against Sri Lanka at Eden Gardens, Kolkata on 13 November 2014 — the highest individual score in ODI cricket history. He has scored 3 double centuries in ODIs, also a record.', source: 'ESPN Cricinfo / ICC records', difficulty: 'medium' },
  { slug: 'spt-hockey-asian-games-2023', categoryId: 'cat-sports', text: 'India won the gold medal in men\'s hockey at the 2023 Asian Games held in which city?', options: ['Jakarta', 'Hangzhou', 'Doha', 'Incheon'], correctIndex: 1, explanation: 'India won the men\'s hockey gold medal at the 2023 Asian Games in Hangzhou, China, defeating Japan 5-1 in the final. This qualified India directly for the 2024 Paris Olympics.', source: 'Asian Games Federation / Indian Olympic Association', difficulty: 'medium' },
  { slug: 'spt-praggnanandhaa-chess-age', categoryId: 'cat-sports', text: 'Rameshbabu Praggnanandhaa became India\'s youngest-ever Grandmaster at what age?', options: ['12 years 10 months', '14 years 2 months', '15 years 6 months', '16 years 0 months'], correctIndex: 0, explanation: 'Praggnanandhaa became a Grandmaster at age 12 years 10 months in 2018 (later surpassed by Abhimanyu Mishra of the USA). He reached the Chess World Cup final in 2023, losing only to Magnus Carlsen.', source: 'World Chess Federation (FIDE)', difficulty: 'hard' },
  { slug: 'spt-badminton-thomas-cup-2022', categoryId: 'cat-sports', text: 'India won its first Thomas Cup (men\'s badminton team championship) in which year?', options: ['2018', '2020', '2022', '2024'], correctIndex: 2, explanation: 'India won its first Thomas Cup in 2022, defeating Indonesia 3-0 in the final in Bangkok. The team included Lakshya Sen, Kidambi Srikanth, Satwiksairaj Rankireddy, and Chirag Shetty.', source: 'Badminton World Federation (BWF) / Badminton Association of India', difficulty: 'medium' },
  { slug: 'spt-javelin-throw-records', categoryId: 'cat-sports', text: 'Neeraj Chopra\'s personal best javelin throw (as of 2024) is approximately how many metres?', options: ['87.58 m', '89.94 m', '91.50 m', '93.00 m'], correctIndex: 1, explanation: 'Neeraj Chopra\'s personal best javelin throw is 89.94 m, achieved at the Stockholm Diamond League on 30 June 2022. He won Olympic gold at Tokyo 2020 with 87.58 m and World Championship gold in 2023.', source: 'World Athletics / Athletics Federation of India', difficulty: 'medium' },
  { slug: 'spt-wrestling-olympic-medals-india', categoryId: 'cat-sports', text: 'As of 2024, wrestling has contributed the most individual Olympic medals for India. How many wrestling Olympic medals has India won (total, men + women)?', options: ['3', '5', '7', '10'], correctIndex: 2, explanation: 'As of 2024, India has won 7 Olympic medals in wrestling: K.D. Jadhav (bronze, 1952), Sushil Kumar (bronze 2008, silver 2012), Yogeshwar Dutt (bronze 2012), Sakshi Malik (bronze 2016), Ravi Dahiya (silver 2020), Bajrang Punia (bronze 2020), and Aman Sehrawat (bronze 2024).', source: 'International Olympic Committee / Wrestling Federation of India', difficulty: 'hard' },
  { slug: 'spt-para-athletics-avad', categoryId: 'cat-sports', text: 'Devendra Jhajharia became the first Indian Paralympian to win two individual gold medals. In which sport?', options: ['Javelin throw', 'Shot put', 'High jump', 'Swimming'], correctIndex: 0, explanation: 'Devendra Jhajharia won Paralympic gold in javelin throw (F46 category) at the 2004 Athens and 2016 Rio Paralympics. He was the first Indian Paralympian to win two gold medals at the Paralympic Games. India has won a total of 29 Paralympic medals (as of 2024).', source: 'International Paralympic Committee (IPC) / Paralympic Committee of India', difficulty: 'hard' },

  // ═══ cat-culture: Culture & Heritage (10) ═══
  { slug: 'cul-elephanta-caves-deity', categoryId: 'cat-culture', text: 'The Elephanta Caves, a UNESCO World Heritage Site near Mumbai, are primarily dedicated to which deity?', options: ['Vishnu', 'Shiva', 'Brahma', 'Ganesha'], correctIndex: 1, explanation: 'The Elephanta Caves (5th-6th century CE) are primarily dedicated to Lord Shiva. They contain rock-cut sculptures including the famous 20-foot-tall Trimurti (three-faced Shiva) and the Ardhanarishvara sculpture. They are a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-durga-puja-unesco', categoryId: 'cat-culture', text: 'Durga Puja in Kolkata was inscribed on UNESCO\'s Intangible Cultural Heritage list in which year?', options: ['2019', '2020', '2021', '2022'], correctIndex: 2, explanation: 'Durga Puja in Kolkata was inscribed on UNESCO\'s Representative List of the Intangible Cultural Heritage of Humanity in December 2021. It recognised the 10-day festival\'s significance as a cultural celebration of goddess Durga.', source: 'UNESCO Intangible Cultural Heritage List', difficulty: 'medium' },
  { slug: 'cul-meenakshi-temple-location', categoryId: 'cat-culture', text: 'The famous Meenakshi Amman Temple is located in which Indian city?', options: ['Madurai', 'Tiruchirapalli', 'Thanjavur', 'Rameswaram'], correctIndex: 0, explanation: 'The Meenakshi Amman Temple is located in Madurai, Tamil Nadu. Dedicated to Goddess Meenakshi (a form of Parvati) and Lord Sundareshwarar (Shiva), it is one of the largest and most historic temple complexes in India, dating to the Pandya dynasty.', source: 'Archaeological Survey of India / Department of Tourism, Tamil Nadu', difficulty: 'easy' },
  { slug: 'cul-thiruvathira-festival', categoryId: 'cat-culture', text: 'Thiruvathira is a festival celebrated mainly in which Indian state?', options: ['Tamil Nadu', 'Kerala', 'Karnataka', 'Andhra Pradesh'], correctIndex: 1, explanation: 'Thiruvathira is a festival celebrated mainly in Kerala, dedicated to Lord Shiva and Goddess Parvati. It falls on the Thiruvathira nakshatra (star) in the Malayalam month of Dhanu (December-January). Women perform a special dance called Thiruvathirakali.', source: 'Department of Tourism, Kerala / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-hampi-vijayanagara-capital', categoryId: 'cat-culture', text: 'The ruins of Hampi, the capital of the Vijayanagara Empire, are located in which state?', options: ['Andhra Pradesh', 'Karnataka', 'Telangana', 'Tamil Nadu'], correctIndex: 1, explanation: 'Hampi is located in the Bellary district of Karnataka. It was the capital of the Vijayanagara Empire (1336-1646 CE). The ruins are a UNESCO World Heritage Site and include the Virupaksha Temple, Vittala Temple (with stone chariot), and Lotus Mahal.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'easy' },
  { slug: 'cul-yakshagana-state', categoryId: 'cat-culture', text: 'Yakshagana, a traditional theatre form combining dance, music, and dialogue, is from which state?', options: ['Kerala', 'Karnataka', 'Tamil Nadu', 'Andhra Pradesh'], correctIndex: 1, explanation: 'Yakshagana is a traditional theatre form from Karnataka, particularly the coastal districts of Dakshina Kannada and Udupi. It combines dance, music, dialogue, and elaborate costumes, typically depicting stories from Hindu epics.', source: 'Sangeet Natak Akademi / Karnataka State Government', difficulty: 'medium' },
  { slug: 'cul-baul-music-bengal', categoryId: 'cat-culture', text: 'The Baul tradition, a syncretic spiritual music tradition, originated in which region?', options: ['Punjab', 'Bengal (Bangladesh and West Bengal)', 'Rajasthan', 'Assam'], correctIndex: 1, explanation: 'The Baul tradition originated in Bengal (including present-day Bangladesh and West Bengal). Bauls are mystic minstrels who sing spiritual songs influenced by Hindu Bhakti and Sufi traditions. The Baul tradition was inscribed on UNESCO\'s Intangible Cultural Heritage list in 2008.', source: 'UNESCO Intangible Cultural Heritage / Sangeet Natak Akademi', difficulty: 'medium' },
  { slug: 'cul-pongal-harvest-festival', categoryId: 'cat-culture', text: 'Pongal, the four-day harvest festival, is primarily celebrated in which Indian state?', options: ['Karnataka', 'Andhra Pradesh', 'Tamil Nadu', 'Kerala'], correctIndex: 2, explanation: 'Pongal is the four-day harvest festival of Tamil Nadu, celebrated in mid-January (Thai month). The four days are Bhogi, Thai Pongal, Mattu Pongal, and Kaanum Pongal. It corresponds to Makar Sankranti in North India.', source: 'Department of Tourism, Tamil Nadu / Ministry of Culture', difficulty: 'easy' },
  { slug: 'cul-rashtrapati-bhavan-arch', categoryId: 'cat-culture', text: 'The Rashtrapati Bhavan (Presidential Residence) in New Delhi was designed by which architect?', options: ['Le Corbusier', 'Edwin Lutyens', 'Herbert Baker', 'Walter George'], correctIndex: 1, explanation: 'The Rashtrapati Bhavan was designed by British architect Edwin Lutyens. It was completed in 1929 as the Viceroy\'s House and is one of the largest residential buildings for a head of state in the world. The Mughal Gardens within the complex are also Lutyens\' design.', source: 'Archaeological Survey of India / Rashtrapati Bhavan', difficulty: 'medium' },
  { slug: 'cul-classical-music-tala-system', categoryId: 'cat-culture', text: 'In Indian classical music, the rhythmic framework is called what?', options: ['Raga', 'Tala', 'Svara', 'Alap'], correctIndex: 1, explanation: 'Tala is the rhythmic framework in Indian classical music. It is a cycle of beats (matras) that repeats throughout a performance. The most common tala in Hindustani music is teental (16 beats). Raga refers to the melodic framework.', source: 'Sangeet Natak Akademi', difficulty: 'medium' },

  // ═══ cat-economy: Economy (10) ═══
  { slug: 'eco-startup-definition-recognition', categoryId: 'cat-economy', text: 'Under the Startup India initiative, an entity is recognised as a "startup" for how many years from its date of incorporation?', options: ['5 years', '7 years', '10 years', '15 years'], correctIndex: 2, explanation: 'Under the Startup India initiative, an entity is recognised as a startup for up to 10 years from its date of incorporation/registration. It must also have an annual turnover not exceeding Rs. 100 crore in any financial year since incorporation.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / Startup India', difficulty: 'medium' },
  { slug: 'eco-rbi-monetary-policy-report-frequency', categoryId: 'cat-economy', text: 'The Monetary Policy Committee (MPC) of the RBI meets how many times a year?', options: ['2 times', '4 times', '6 times', '8 times'], correctIndex: 2, explanation: 'The MPC meets at least 4 times a year, but in practice meets 6 times a year (bi-monthly — every two months). It reviews the macroeconomic situation and sets the policy repo rate.', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-gst-slab-rates', categoryId: 'cat-economy', text: 'How many GST tax slab rates are currently in place in India (as of 2024)?', options: ['3 slabs', '4 slabs', '5 slabs', '6 slabs'], correctIndex: 2, explanation: 'India has 5 GST tax slabs: 0% (essential items), 5% (common-use items), 12%, 18% (standard rate), and 28% (luxury goods). A special rate of 40% applies to some items like pan masala. Gold and diamonds are taxed at 3%.', source: 'GST Council / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-sbi-establishment-year', categoryId: 'cat-economy', text: 'The State Bank of India (SBI) was established in its current form in which year?', options: ['1935', '1947', '1955', '1969'], correctIndex: 2, explanation: 'The State Bank of India was established on 1 July 1955 when the Imperial Bank of India was nationalised and reconstituted as SBI. The Imperial Bank itself was formed in 1921 by merging the Bank of Bengal, Bank of Bombay, and Bank of Madras.', source: 'State Bank of India / Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-current-account-deficit-meaning', categoryId: 'cat-economy', text: 'What does a Current Account Deficit (CAD) indicate for a country?', options: ['The country exports more than it imports', 'The country imports more goods, services, and transfers than it exports', 'The government budget is in deficit', 'The RBI is losing foreign exchange reserves'], correctIndex: 1, explanation: 'A Current Account Deficit means a country imports more goods, services, and income transfers than it exports. It is funded by capital inflows (foreign investment, borrowing). A moderate CAD is normal for a developing country like India.', source: 'Reserve Bank of India / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-fiscal-federalism-fc', categoryId: 'cat-economy', text: 'The Finance Commission of India is constituted under which Article of the Constitution?', options: ['Article 246', 'Article 263', 'Article 280', 'Article 315'], correctIndex: 2, explanation: 'Article 280 of the Constitution provides for the constitution of a Finance Commission every five years. It recommends the distribution of tax revenues between the Centre and States and among States themselves. The 15th Finance Commission\'s recommendations cover 2021-22 to 2025-26.', source: 'Constitution of India, Article 280', difficulty: 'hard' },
  { slug: 'eco-fdi-sectors-prohibited', categoryId: 'cat-economy', text: 'In which sector is FDI completely prohibited in India (as of 2024)?', options: ['Banking', 'Insurance', 'Lottery and gambling', 'Telecommunications'], correctIndex: 2, explanation: 'FDI is completely prohibited in lottery businesses, gambling and betting, chit funds, nidhi companies, trading in transferable development rights (TDRs), real estate business (but townships/cities allowed), and manufacturing of cigars/cigarettes using tobacco.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / FEMA Regulations', difficulty: 'hard' },
  { slug: 'eco-cpi-vs-wpi-meaning', categoryId: 'cat-economy', text: 'What is the key difference between the Consumer Price Index (CPI) and the Wholesale Price Index (WPI)?', options: ['CPI measures factory output; WPI measures retail prices', 'CPI measures retail prices; WPI measures wholesale/trade-level prices', 'CPI is for goods only; WPI is for services only', 'There is no difference'], correctIndex: 1, explanation: 'CPI measures the change in retail prices of goods and services consumed by households. WPI measures the change in prices at the wholesale/trade level (goods only, no services). RBI uses CPI (Combined) as its primary inflation measure since 2014.', source: 'Ministry of Statistics and Programme Implementation (MoSPI) / RBI', difficulty: 'medium' },
  { slug: 'eco-ripple-effect-jandhan', categoryId: 'cat-economy', text: 'How many Jan Dhan bank accounts had been opened by approximately 2024 since the scheme\'s launch?', options: ['About 100 million', 'About 300 million', 'About 500 million', 'About 750 million'], correctIndex: 2, explanation: 'Approximately 500 million (50 crore) Jan Dhan accounts had been opened by 2024, with total deposits exceeding Rs. 2 lakh crore. The scheme launched in August 2014 has been one of the world\'s largest financial inclusion programmes.', source: 'Ministry of Finance / Department of Financial Services', difficulty: 'medium' },
  { slug: 'eco-electricity-act-year', categoryId: 'cat-economy', text: 'The Electricity Act, which reformed India\'s power sector by introducing competition, was enacted in which year?', options: ['1998', '2001', '2003', '2010'], correctIndex: 2, explanation: 'The Electricity Act, 2003 consolidated laws relating to generation, transmission, distribution, and trading of electricity. It introduced competition, delicensed generation (except hydro), and mandated open access to transmission.', source: 'Ministry of Power, Government of India', difficulty: 'hard' },

  // ═══ cat-environment: Environment & Wildlife (10) ═══
  { slug: 'env-tiger-reserves-count-2024', categoryId: 'cat-environment', text: 'As of 2024, how many tiger reserves does India have?', options: ['About 35', 'About 45', 'About 55', 'About 65'], correctIndex: 2, explanation: 'As of 2024, India has approximately 55 tiger reserves. The first tiger reserve was Jim Corbett (established in 1936 as a national park, designated tiger reserve in 1973 under Project Tiger). India has about 75% of the world\'s wild tigers.', source: 'National Tiger Conservation Authority (NTCA) / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-snow-leopard-habitat-states', categoryId: 'cat-environment', text: 'In India, the snow leopard is found in the wild in how many states/UTs?', options: ['2', '3', '5', '7'], correctIndex: 2, explanation: 'In India, the snow leopard is found in 5 Himalayan states/UTs: Ladakh, Himachal Pradesh, Uttarakhand, Sikkim, and Arunachal Pradesh. India\'s snow leopard population is estimated at about 718 individuals (SPAI report, 2024).', source: 'Ministry of Environment, Forest and Climate Change / Wildlife Institute of India', difficulty: 'hard' },
  { slug: 'env-india-forest-cover-percentage', categoryId: 'cat-environment', text: 'According to the India State of Forest Report 2021, what percentage of India\'s geographical area is under forest cover?', options: ['About 12%', 'About 21%', 'About 33%', 'About 45%'], correctIndex: 1, explanation: 'According to the India State of Forest Report 2021 (Forest Survey of India), India\'s forest cover is approximately 21.71% of its total geographical area (713,789 sq km out of 3,287,263 sq km). The target is 33% under the National Forest Policy, 1988.', source: 'Forest Survey of India, Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-cleantech-ev-adoption', categoryId: 'cat-environment', text: 'India\'s FAME-II scheme (Faster Adoption and Manufacturing of Electric Vehicles) primarily subsidises which type of vehicles?', options: ['Only electric cars', 'Electric two-wheelers, three-wheelers, four-wheelers, and buses', 'Only electric buses', 'Only hybrid vehicles'], correctIndex: 1, explanation: 'FAME-II (launched in 2019, Rs. 10,000 crore outlay) subsidises electric two-wheelers, three-wheelers, four-wheelers, and buses. It aims to promote EV adoption and indigenous manufacturing. The scheme ended in March 2024, succeeded by the EMPS scheme.', source: 'Ministry of Heavy Industries / NITI Aayog', difficulty: 'medium' },
  { slug: 'env-cop26-panchamrit', categoryId: 'cat-environment', text: 'At COP26 (2021), India announced "Panchamrit" — five climate commitments. Which is one of them?', options: ['Net zero by 2040', '500 GW non-fossil fuel energy capacity by 2030', '100% electric vehicles by 2030', 'Ban on coal by 2030'], correctIndex: 1, explanation: 'At COP26, India announced "Panchamrit" — five climate commitments: (1) 500 GW non-fossil capacity by 2030, (2) 50% energy from renewables by 2030, (3) 1 billion tonnes CO2 reduction by 2030, (4) 45% carbon intensity reduction by 2030, (5) Net zero by 2070.', source: 'UNFCCC COP26 / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-wetlands-convention-india', categoryId: 'cat-environment', text: 'India became a party to the Ramsar Convention on Wetlands in which year?', options: ['1971', '1982', '1992', '2002'], correctIndex: 1, explanation: 'India became a party to the Ramsar Convention in 1982. As of early 2024, India has 75+ Ramsar Sites (wetlands of international importance), covering about 1.33 million hectares — the largest network in South Asia.', source: 'Ministry of Environment, Forest and Climate Change / Ramsar Convention Secretariat', difficulty: 'medium' },
  { slug: 'env-water-day-theme-2024', categoryId: 'cat-environment', text: 'World Environment Day 2023 was hosted by which country?', options: ['India', 'Côte d\'Ivoire (Ivory Coast)', 'Sweden', 'China'], correctIndex: 1, explanation: 'World Environment Day 2023 was hosted by Côte d\'Ivoire (Ivory Coast) with the theme "Solutions to Plastic Pollution". India hosted it in 2018 and 2011. World Environment Day is observed annually on 5 June since 1974.', source: 'United Nations Environment Programme (UNEP)', difficulty: 'hard' },
  { slug: 'env-great-indian-bustard', categoryId: 'cat-environment', text: 'The Great Indian Bustard, one of India\'s most critically endangered birds, is the state bird of which state?', options: ['Gujarat', 'Rajasthan', 'Madhya Pradesh', 'Maharashtra'], correctIndex: 1, explanation: 'The Great Indian Bustard (Godawan) is the state bird of Rajasthan. It is critically endangered with fewer than 150 individuals remaining in the wild. The main threats are habitat loss (grasslands) and collision with power transmission lines.', source: 'IUCN Red List / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-campaign-clean-rivers', categoryId: 'cat-environment', text: 'The National Mission for Clean Ganga (NMCG) is implemented by which ministry?', options: ['Ministry of Environment', 'Ministry of Jal Shakti', 'Ministry of Rural Development', 'Ministry of Urban Development'], correctIndex: 1, explanation: 'The National Mission for Clean Ganga (NMCG) is implemented by the Ministry of Jal Shakti (Water Resources). It was registered as a society in 2011 and aims to clean the Ganga river by addressing pollution from domestic, industrial, and agricultural sources.', source: 'National Mission for Clean Ganga / Ministry of Jal Shakti', difficulty: 'medium' },
  { slug: 'env-copper-toxicity-lion', categoryId: 'cat-environment', text: 'The Gir Forest National Park, home to the Asiatic lion, is located in which district of Gujarat?', options: ['Junagadh', 'Amreli', 'Bhavnagar', 'Rajkot'], correctIndex: 0, explanation: 'Gir Forest National Park and Wildlife Sanctuary is primarily located in Junagadh district, Gujarat. It spans about 1,412 sq km and is the only natural habitat of the Asiatic lion (Panthera leo persica), with about 670 lions (2020 census).', source: 'Gujarat Forest Department / Ministry of Environment', difficulty: 'medium' },

  // ═══ cat-art: Art, Literature & Languages (10) ═══
  { slug: 'art-tagore-shantiniketan-unesco', categoryId: 'cat-art', text: 'Santiniketan, the educational and cultural centre established by Rabindranath Tagore, was inscribed as a UNESCO World Heritage Site in which year?', options: ['2018', '2020', '2023', '2024'], correctIndex: 2, explanation: 'Santiniketan was inscribed as a UNESCO World Heritage Site in September 2023. Established by Rabindranath Tagore in 1901, it later became Visva-Bharati University (1921). It represents a unique fusion of Indian and pan-Asian educational traditions.', source: 'UNESCO World Heritage List / Visva-Bharati University', difficulty: 'medium' },
  { slug: 'art-charminar-builder', categoryId: 'cat-art', text: 'The Charminar monument in Hyderabad was built by which ruler?', options: ['Quli Qutb Shah', 'Asaf Jah I (Nizam)', 'Ibrahim Qutb Shah', 'Muhammad Quli Qutb Shah'], correctIndex: 3, explanation: 'The Charminar was built in 1591 by Muhammad Quli Qutb Shah, the fifth ruler of the Qutb Shahi dynasty, to commemorate the end of a plague epidemic. It is a square structure with four grand arches and four minarets, located in the heart of Hyderabad.', source: 'Archaeological Survey of India / Department of Tourism, Telangana', difficulty: 'medium' },
  { slug: 'art-indian-classical-music-instruments', categoryId: 'cat-art', text: 'The sitar, one of the most famous Indian classical musical instruments, is believed to have been developed during which period?', options: ['Vedic period', 'Mughal period', 'Colonial period', 'Post-independence'], correctIndex: 1, explanation: 'The sitar is believed to have been developed during the Mughal period (c. 13th-14th century), evolving from the Persian setar and the Indian veena. It was popularised by musicians like Ravi Shankar and Vilayat Khan in the 20th century.', source: 'Sangeet Natak Akademi / Sangeet Research Academy', difficulty: 'medium' },
  { slug: 'art-mahabharata-author', categoryId: 'cat-art', text: 'The Mahabharata, the world\'s longest epic, is traditionally attributed to which sage?', options: ['Valmiki', 'Vyasa', 'Kalidasa', 'Panini'], correctIndex: 1, explanation: 'The Mahabharata is traditionally attributed to Sage Vyasa (also known as Krishna Dvaipayana Vyasa). He is also said to have compiled the four Vedas. The epic contains about 100,000 verses and is the longest poem ever written.', source: 'Sahitya Akademi / Encyclopaedia Britannica', difficulty: 'easy' },
  { slug: 'art-bharatanatyam-instruments', categoryId: 'cat-art', text: 'In a Bharatanatyam performance, which musical instrument traditionally provides the rhythmic accompaniment?', options: ['Sitar', 'Tabla', 'Nattuvangam (cymbals)', 'Harmonium'], correctIndex: 2, explanation: 'The Nattuvangam (a pair of cymbals) is the traditional rhythmic instrument used in Bharatanatyam performances. The Nattuvanar (person playing the Nattuvangam) also recites rhythmic syllables (sollukattu) and guides the dancer. Mridangam provides percussion accompaniment.', source: 'Sangeet Natak Akademi', difficulty: 'hard' },
  { slug: 'art-dhrupad-tradition-origin', categoryId: 'cat-art', text: 'Dhrupad, the oldest surviving style of Hindustani classical music, traces its origins to which tradition?', options: ['Sufi music', 'Vedic chanting and temple music', 'Mughal court music', 'Folk music of Rajasthan'], correctIndex: 1, explanation: 'Dhrupad traces its origins to Vedic chanting and temple music. It evolved as a vocal style in the 15th century, particularly associated with the Dagar family (Dagar Gharana). It emphasises pure melody (alap) without words in the initial sections.', source: 'Sangeet Natak Akademi / India International Centre', difficulty: 'hard' },
  { slug: 'art-pahari-painting-style', categoryId: 'cat-art', text: 'Pahari painting, a style of Indian miniature painting, originated in which region?', options: ['Rajasthan', 'Himalayan foothills (Himachal Pradesh and J&K)', 'Deccan plateau', 'Bengal'], correctIndex: 1, explanation: 'Pahari painting originated in the Himalayan foothills — the hill states of Himachal Pradesh and Jammu & Kashmir (Basohli, Kangra, Guler, Chamba). It flourished from the 17th to 19th centuries and is known for its lyrical, devotional depictions of Krishna and Radha.', source: 'National Museum, New Delhi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'art-tagore-gitanjali-year', categoryId: 'cat-art', text: 'Rabindranath Tagore received the Nobel Prize in Literature in which year?', options: ['1905', '1913', '1915', '1921'], correctIndex: 1, explanation: 'Tagore received the Nobel Prize in Literature in 1913, becoming the first Asian and non-European Nobel laureate. He was awarded for "Gitanjali" (Song Offerings), a collection of 157 poems. He translated it into English himself.', source: 'Nobel Prize Foundation', difficulty: 'easy' },
  { slug: 'art-mughal-architecture-taj', categoryId: 'cat-art', text: 'The Taj Mahal was commissioned by Mughal Emperor Shah Jahan as a mausoleum for which person?', options: ['His mother', 'His wife Mumtaz Mahal', 'His father', 'His daughter'], correctIndex: 1, explanation: 'The Taj Mahal was commissioned by Shah Jahan as a mausoleum for his beloved wife, Mumtaz Mahal (Arjumand Banu Begum), who died in 1631 during childbirth. Construction began in 1632 and was completed in 1653. It is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'easy' },
  { slug: 'art-modern-art-gallery-india', categoryId: 'cat-art', text: 'The National Gallery of Modern Art (NGMA) in India has its main branch in which city?', options: ['Mumbai', 'New Delhi', 'Bengaluru', 'Kolkata'], correctIndex: 1, explanation: 'The main branch of the National Gallery of Modern Art (NGMA) is in New Delhi (established in 1954 at Jaipur House). NGMA also has branches in Mumbai (2009) and Bengaluru (2009). It houses over 17,000 works of modern and contemporary Indian art.', source: 'National Gallery of Modern Art / Ministry of Culture', difficulty: 'medium' },

  // ═══ cat-edu: Education (10) ═══
  { slug: 'edu-iit-first-director', categoryId: 'cat-edu', text: 'Who was the first Director of IIT Kharagpur (India\'s first IIT)?', options: ['Dr. B.C. Roy', 'J.C. Ghosh', 'Meghnad Saha', 'Homi Bhabha'], correctIndex: 1, explanation: 'Dr. J.C. Ghosh was the first Director of IIT Kharagpur (1951-1955). He was a renowned chemist. The institute was inaugurated on 18 August 1951 in the Hijli Detention Camp building, which now houses the Nehru Museum of Science and Technology.', source: 'IIT Kharagpur official website / Ministry of Education', difficulty: 'hard' },
  { slug: 'edu-aiims-aiims-act', categoryId: 'cat-edu', text: 'How many AIIMS (All India Institutes of Medical Sciences) were approved to be set up under Phase VI of PMSSY (approximately, as of 2024)?', options: ['14', '17', '22+', '30'], correctIndex: 2, explanation: 'As of 2024, approximately 22+ AIIMS have been sanctioned under the Pradhan Mantri Swasthya Suraksha Yojana (PMSSY), in addition to AIIMS New Delhi (established 1956). Several are in various stages of development and operationalization.', source: 'Ministry of Health and Family Welfare / PMSSY', difficulty: 'hard' },
  { slug: 'edu-neet-conducting-body', categoryId: 'cat-edu', text: 'Since 2019, NEET (medical entrance exam) has been conducted by which organisation?', options: ['CBSE', 'National Testing Agency (NTA)', 'AIIMS', 'Medical Council of India'], correctIndex: 1, explanation: 'Since 2019, NEET is conducted by the National Testing Agency (NTA), which was established in 2017. From 2013-2018, CBSE conducted NEET. NEET is the sole entrance test for MBBS and BDS admissions in India.', source: 'National Testing Agency (NTA) / Ministry of Health', difficulty: 'medium' },
  { slug: 'edu-iim-calcutta-first', categoryId: 'cat-edu', text: 'Which was the first Indian Institute of Management (IIM) to be established?', options: ['IIM Ahmedabad', 'IIM Calcutta', 'IIM Bangalore', 'IIM Lucknow'], correctIndex: 1, explanation: 'IIM Calcutta was the first IIM, established in November 1961, followed by IIM Ahmedabad in December 1961 and IIM Bangalore in 1973. IIM Calcutta was established in collaboration with the MIT Sloan School of Management and the Government of West Bengal.', source: 'IIM Calcutta / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-digi-platforms-initiative', categoryId: 'cat-edu', text: 'SWAYAM, the Indian government\'s MOOC platform, was launched in which year?', options: ['2014', '2016', '2018', '2020'], correctIndex: 1, explanation: 'SWAYAM (Study Webs of Active-Learning for Young Aspiring Minds) was launched in 2016. It offers free online courses from Class 9 to postgraduate level, with certification available for a fee. It is coordinated by IIT Madras, AICTE, UGC, and NPTEL.', source: 'Ministry of Education / SWAYAM official portal', difficulty: 'medium' },
  { slug: 'edu-unesco-learning-city-india', categoryId: 'cat-edu', text: 'Which Indian city was the first to be recognised as a UNESCO Learning City?', options: ['Mumbai', 'Bengaluru', 'Delhi', 'Chennai'], correctIndex: 1, explanation: 'Bengaluru was recognised as India\'s first UNESCO Learning City in September 2023, joining the UNESCO Global Network of Learning Cities (GNLC). The recognition acknowledged the city\'s efforts in promoting lifelong learning, digital inclusion, and educational innovation.', source: 'UNESCO Institute for Lifelong Learning', difficulty: 'hard' },
  { slug: 'edu-national-institution-rankings', categoryId: 'cat-edu', text: 'NIRF (National Institutional Ranking Framework) was launched by the Government of India in which year?', options: ['2013', '2015', '2017', '2019'], correctIndex: 2, explanation: 'NIRF was launched on 29 September 2015 by the Ministry of Education. The first rankings were released in 2016 (covering 2015-16). NIRF ranks institutions based on teaching, learning, research, graduation outcomes, outreach, and perception.', source: 'Ministry of Education / NIRF official website', difficulty: 'medium' },
  { slug: 'edu-right-to-education-act-2009', categoryId: 'cat-edu', text: 'The Right to Education (RTE) Act, 2009 mandates that private schools reserve what percentage of seats for children from disadvantaged backgrounds?', options: ['10%', '15%', '25%', '33%'], correctIndex: 2, explanation: 'The RTE Act, 2009 mandates that all private (unaided) schools reserve 25% of their entry-level seats for children from disadvantaged and Economically Weaker Sections (EWS). This applies to Class 1 or pre-primary, and the government reimburses their fees.', source: 'Ministry of Education / RTE Act, 2009', difficulty: 'medium' },
  { slug: 'edu-nep-2020-5-3-3-4', categoryId: 'cat-edu', text: 'The National Education Policy 2020 introduces a new pedagogical structure. What is the 5+3+3+4 format?', options: ['5 years primary, 3 middle, 3 secondary, 4 higher', '5 years foundational, 3 preparatory, 3 middle, 4 secondary', '5 years secondary, 3 college, 3 postgrad, 4 PhD', '5+3+3+4 makes 15 years of education total'], correctIndex: 1, explanation: 'NEP 2020 introduces a 5+3+3+4 structure: Foundational (5 years, ages 3-8: 3 years Anganwadi/pre-school + 2 years Class 1-2), Preparatory (3 years, ages 8-11: Classes 3-5), Middle (3 years, ages 11-14: Classes 6-8), Secondary (4 years, ages 14-18: Classes 9-12).', source: 'Ministry of Education / NEP 2020', difficulty: 'hard' },
  { slug: 'edu-first-medical-college-india', categoryId: 'cat-edu', text: 'Which is considered the first modern medical college in India?', options: ['AIIMS New Delhi', 'Calcutta Medical College (Kolkata)', 'Madras Medical College', 'Grant Medical College (Mumbai)'], correctIndex: 1, explanation: 'Calcutta Medical College (now Medical College and Hospital, Kolkata) was established on 1 February 1835, making it the first modern medical college in Asia. It was established during the British colonial era by Lord William Bentinck, Governor-General of India.', source: 'Medical College Kolkata / Ministry of Health', difficulty: 'hard' },
];

async function main() {
  console.log('=== Batch 3 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
